async function main() {
  const category = await prisma.interviewCategory.upsert({
    where: { slug: categorySlug },
    update: { name: "C Programming" },
    create: { name: "C Programming", slug: categorySlug },
  });

  const subcategoryMap = new Map<string, string>();

  for (const subcategory of subcategories) {
    const record = await prisma.interviewSubcategory.upsert({
      where: {
        categoryId_slug: {
          categoryId: category.id,
          slug: subcategory.slug,
        },
      },
      update: { name: subcategory.name },
      create: {
        name: subcategory.name,
        slug: subcategory.slug,
        categoryId: category.id,
      },
    });
    subcategoryMap.set(subcategory.slug, record.id);
  }

  for (const item of questions) {
    const subcategoryId = subcategoryMap.get(item.subcategorySlug);
    if (!subcategoryId) {
      throw new Error(`Missing subcategory: ${item.subcategorySlug}`);
    }

    await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        question: item.question,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: item.experienceLevel,
        difficulty: item.difficulty,
        interviewType: item.interviewType,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: item.isPublished,
      },
      create: {
        question: item.question,
        slug: item.slug,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: item.experienceLevel,
        difficulty: item.difficulty,
        interviewType: item.interviewType,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: item.isPublished,
      },
    });
  }

  console.log(`C interview question seed completed successfully: ${questions.length} questions.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
